def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])

    row_modes = [Counter(row).most_common(1)[0] for row in grid]
    col_modes = [
        Counter(grid[r][c] for r in range(h)).most_common(1)
        for c in range(w)
    ]

    def positions(modes, color, length):
        return [i for i, (c, n) in enumerate(modes)
                if c == color and n >= 0.70 * length]

    def spacing_score(pos):
        if len(pos) < 2:
            return (0, 0)
        gaps = [b - a for a, b in zip(pos, pos[1:])]
        gap, count = Counter(gaps).most_common(1)[0]
        # Grid boundaries are periodic and separated by more than one cell.
        if gap <= 1:
            return (0, 0)
        return (count / len(gaps), len(pos))

    colors = {c for c, n in row_modes if n >= 0.70 * w}
    colors.update(c for (c, n) in [m[0] for m in col_modes] if n >= 0.70 * h)

    best = None
    lattice = None
    for color in colors:
        rp = positions(row_modes, color, w)
        cp = positions([m[0] for m in col_modes], color, h)
        rs, cs = spacing_score(rp), spacing_score(cp)
        score = (min(rs[0], cs[0]), rs[0] + cs[0], min(rs[1], cs[1]))
        if best is None or score > best:
            best, lattice = score, color

    rows = positions(row_modes, lattice, w)
    cols = positions([m[0] for m in col_modes], lattice, h)

    background = Counter(v for row in grid for v in row if v != lattice).most_common(1)[0][0]
    out = [[background for _ in range(len(cols) - 1)]
           for _ in range(len(rows) - 1)]

    for i in range(len(rows) - 1):
        for j in range(len(cols) - 1):
            vals = (grid[rows[i]][cols[j]], grid[rows[i]][cols[j + 1]],
                    grid[rows[i + 1]][cols[j]], grid[rows[i + 1]][cols[j + 1]])
            if vals[0] != lattice and vals.count(vals[0]) == 4:
                out[i][j] = vals[0]

    active_rows = [i for i, row in enumerate(out)
                   if any(v != background for v in row)]
    active_cols = [j for j in range(len(out[0]))
                   if any(out[i][j] != background for i in range(len(out)))]
    if not active_rows or not active_cols:
        return [[background]]
    return [row[min(active_cols):max(active_cols) + 1]
            for row in out[min(active_rows):max(active_rows) + 1]]
